{"command":"cat > tests/test_spec.py <<'PY'
import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_is_unflagged_but_in_denominator():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": True}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_last_duplicate_wins_before_sorting():
    events = parse_transcript_log(["b,9,1", "c,0,0", "a,1,1", "b,1,0"])
    assert dedupe_transcripts(events) == [events[1], events[2], events[3]]


def test_parser_skips_and_trims():
    lines = ["", "  \t", "  # comment", " x , 3 , 0 ", " y , -1 ,  "]
    assert parse_transcript_log(lines) == [
        {"id": "x", "day": 3, "flagged": False},
        {"id": "y", "day": -1, "flagged": None},
    ]


@pytest.mark.parametrize("bad", ["x,1", "x,1,0,extra", "x,no,0"])
def test_parser_reports_original_line_number(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# comment", "x,0,1", " ", bad])


def test_daily_counts_and_windows():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,3,1", "e,4,1"])
    counts = daily_flag_counts(events, 1, 3)
    assert counts == [2, 0, 1]
    assert daily_flag_counts(events, 2, 1) == []
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 2) == 1
    assert flags_in_window(counts, 9) == 3


def test_pooled_rate_and_summary():
    groups = {"a": parse_transcript_log(["x,1,1", "y,1,0"]),
              "b": parse_transcript_log(["z,4,1"]), "empty": []}
    assert pooled_flag_rate(groups) == 2 / 3
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_order_and_empty_groups():
    groups = {"c": [{"flagged": True}], "b": [{"flagged": False}],
              "a": [{"flagged": True}], "empty": []}
    assert top_flagged_groups(groups, 10) == ["a", "c", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert list(flag_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", 0.0), ("c", 1.0), ("empty", None),
    ]


def test_streak_counts_consecutive_positive_days():
    assert longest_flag_streak([1, 0, 1, 2, -1, 3]) == 2
    assert longest_flag_streak([]) == longest_flag_streak([0, -1]) == 0
